function th(t: any) {
  if (!t) return null;
  if (typeof t === "number") return t;
  if (t && typeof t.toDate === "function") {
    try { return t.toDate().getTime(); } catch {}
  }
  if (typeof t === "string") {
    try { return new Date(t).getTime(); } catch {}
  }
  return null;
}

