export function subscribeToTransactionStatus(txId: string, callback: (status: string, tx: any) => void) {
  if (!txId) return () => {};
  try {
    const unsub = onSnapshot(doc(db, "transactions", txId), (snap) => {
      if (snap.exists()) {
        const data = snap.data();
        callback(data.status || "PENDING", data);
      }
    }, (err) => {
      console.warn("[subscribeToTransactionStatus warn]:", err);
    });
    return unsub;
  } catch (err) {
    console.warn("[subscribeToTransactionStatus err]:", err);
    return () => {};
  }
}

export const resolveSupportTicket = async (id: string, resolvedBy: string = "Support Dokya") => {
  try {
    const chatRef = doc(db, "support_chats", id);
    await updateDoc(chatRef, {
      status: "resolved",
      resolvedAt: serverTimestamp(),
      resolvedBy,
      needsHumanSupport: false,
      updatedAt: serverTimestamp()
    });
    return true;
  } catch (err) {
    console.warn("[resolveSupportTicket err]:", err);
    return false;
  }
};


